"""Compare M3's projection with facts generated by BPA-X itself, independent of IDs."""

import argparse
from collections import Counter
from functools import lru_cache
import json
import os
from pathlib import Path
import subprocess
import sys

from bpa.pipeline import run_m3
from bpa.vex.compat import write_projection


ROOT = Path(__file__).resolve().parents[1]
BPAX = Path("/home/qc/Desktop/rebuild/bpa_x")
REFERENCE_PYTHON = Path("/home/qc/Desktop/binwork/mywork/BPA/.venv/bin/python")
READELF_BIN = Path("/home/qc/Desktop/binwork/bpa-x/.venv/bin")
VEX_EXPRESSIONS = ("imm_vex_exp", "get_loc_vex_exp", "get_tmp_reg_vex_exp", "get_mem_vex_exp",
                   "unop_vex_exp", "binop_vex_exp", "if_vex_exp")
DL_EXPRESSIONS = ("binop_dl_exp", "unop_dl_exp", "cast_s_dl_exp", "cast_u_dl_exp")
ASSIGNMENTS = ("set_loc_vex", "set_tmp_reg_vex", "set_mem_vex")


def read_rows(directory, names):
    return {name: [tuple(line.split("\t")) for line in (directory / f"{name}.facts").read_text().splitlines()]
            for name in names}


def canonicalize(rows, dl=False):
    definitions = {}
    for name in VEX_EXPRESSIONS + (DL_EXPRESSIONS if dl else ()):
        for row in rows[name]:
            definitions[row[0]] = name, row[1:]

    @lru_cache(None)
    def expression(eid):
        if eid == "0":
            return ("unknown",)
        if eid not in definitions:
            raise ValueError(f"Dangling expression in comparison: {eid}")
        name, values = definitions[eid]
        if name in ("imm_vex_exp", "get_loc_vex_exp", "get_tmp_reg_vex_exp"):
            return (name, *values)
        if name in ("get_mem_vex_exp", "unop_vex_exp"):
            return (name, values[0], expression(values[1]))
        if name in ("binop_vex_exp", "binop_dl_exp"):
            return (name, values[0], values[1], expression(values[2]), expression(values[3]))
        if name in ("unop_dl_exp", "cast_s_dl_exp", "cast_u_dl_exp"):
            return (name, values[0], values[1], expression(values[2]))
        return (name, *(expression(value) for value in values))

    result = {}
    for name in (DL_EXPRESSIONS if dl else VEX_EXPRESSIONS):
        # Constants are globally deduplicated by BPA-X and by the adapter.
        result[name] = Counter(expression(row[0]) for row in rows[name])
    for name in ASSIGNMENTS:
        result[name] = Counter((row[0], row[1], row[2], expression(row[3]),
                                expression(row[4]) if name == "set_mem_vex" else row[4])
                               for row in rows[name])
    if not dl:
        for name in ("imark_vex", "instr_vex"):
            result[name] = Counter(rows[name])
    return result


def compare(binary, output, bpax=BPAX, reference_python=REFERENCE_PYTHON, readelf_bin=READELF_BIN):
    raw = run_m3(binary, output / "ours")
    if raw.metadata["load_bias"]:
        raise ValueError("This comparison helper currently requires ELF VA == mapped VA (non-PIE fixtures)")
    projected = output / "projected"
    write_projection(raw, projected, protected=[binary])
    reference = output / "reference"
    reference.mkdir(parents=True, exist_ok=True)
    command = [str(reference_python), str(bpax / "vex_fact_gen/gen_facts.py"),
               str(binary.resolve()), raw.metadata["arch"], str(reference.resolve())]
    env = dict(os.environ, PATH=str(readelf_bin) + os.pathsep + os.environ.get("PATH", ""))
    completed = subprocess.run(command, cwd=bpax / "vex_fact_gen", env=env,
                               capture_output=True, text=True, timeout=120)
    if completed.returncode:
        raise RuntimeError(completed.stdout + completed.stderr)
    names = VEX_EXPRESSIONS + DL_EXPRESSIONS + ASSIGNMENTS + ("imark_vex", "instr_vex")
    ours, theirs = read_rows(projected, names), read_rows(reference, names)
    checks, differences = {}, {}
    for dl in (False, True):
        left, right = canonicalize(ours, dl), canonicalize(theirs, dl)
        for name in left:
            key = ("datalog/" if dl else "vex/") + name
            checks[key] = left[name] == right[name]
            if not checks[key]:
                extra, missing = left[name] - right[name], right[name] - left[name]
                differences[key] = dict(only_ours=sum(extra.values()), only_reference=sum(missing.values()),
                                        examples_ours=[repr(row) for row in list(extra)[:5]],
                                        examples_reference=[repr(row) for row in list(missing)[:5]])
    report = dict(binary=str(binary.resolve()), binary_sha256=raw.metadata["binary_sha256"],
                  status="passed" if all(checks.values()) else "failed", checks=checks,
                  counts={name: dict(ours=len(ours[name]), reference=len(theirs[name])) for name in names},
                  scope="BPA-X instruction facts and converted arithmetic; IDs replaced by expression structures; no M4 or points-to solver",
                  differences=differences)
    (output / "comparison.json").write_text(json.dumps(report, indent=2) + "\n")
    print(json.dumps(report, indent=2))
    return 0 if report["status"] == "passed" else 1


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("binary", type=Path)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--bpax-root", type=Path, default=BPAX)
    parser.add_argument("--reference-python", type=Path, default=REFERENCE_PYTHON)
    parser.add_argument("--readelf-bin", type=Path, default=READELF_BIN)
    args = parser.parse_args()
    sys.exit(compare(args.binary, args.output, args.bpax_root, args.reference_python, args.readelf_bin))
